// Light-Activated Night Lamp
// Turns an LED on when ambient light drops below a threshold.

const int LDR_PIN = A0;
const int LAMP_PIN = 9;

// Adjust this after testing in your actual room lighting — see Troubleshooting.
const int DARK_THRESHOLD = 400;

void setup() {
  pinMode(LAMP_PIN, OUTPUT);
  Serial.begin(9600); // for tuning the threshold — see step 1 below
}

void loop() {
  int lightLevel = analogRead(LDR_PIN);
  Serial.println(lightLevel); // watch this in the Serial Monitor while testing

  if (lightLevel > DARK_THRESHOLD) {
    digitalWrite(LAMP_PIN, HIGH); // dark enough — turn the lamp on
  } else {
    digitalWrite(LAMP_PIN, LOW);
  }

  delay(200);
}
